use xiom.io;

use xiom.string;
fn factorial(n: Int) -> Int
  requires: n >= 0;
  ensures: result >= 1;
{
  if n == 0 { return 1; }
  else {
    let f = 1;
    let i = 1;
    while i <= n { f = f * i; i = i + 1; }
    return f;
  }
}

fn main() -> Int {
  let f = factorial(5);
  io.println(to_string(f));
  return 0;
}
